      const setVista = (modulo, valor) => prepareDb(dbPath, [setVistaOperativaStatement(modulo, "colaborador", valor)]);

      const fxPermisos = await crearCompraRecepcionFixtureF3E3D1(baseUrl, adminToken, dbPath, { cantidadComprada: 4 });
