      const fxRevertida = await crearCompraRecepcionFixtureF3E3D1(baseUrl, token, dbPath, { cantidadComprada: 10, stockInicial: 0 });
      const recepcionRevertida = await fxRevertida.recibir(10, "f3e3e1-no-candidato-revertida");
