    const empresa = await registrarEmpresa(controlDb, { slug: empresaSlug, nombre: "Resolver No Leak Test", dbPath: "guernica.db" });
    const hashConocido = await bcrypt.hash("SecretoQueNuncaDebeSalir1", 10);
