async function testMT1C2B2AControlDbInaccesible() {
  // Mismo patron que testMT1C2AResolverControlDbInaccesible: un directorio real, existe pero no
  // es abrible como SQLite. Como autenticarCredencialCentral llama primero al resolver, este
  // fallo se propaga desde ahi -- certifica que el servicio de seguridad no lo reclasifica ni lo
  // envuelve como CREDENCIAL_INVALIDA.
  const controlDbPathDirectorio = path.join(os.tmpdir(), `sec-inaccesible-${Date.now()}-${Math.random().toString(16).slice(2)}`);
  fs.mkdirSync(controlDbPathDirectorio, { recursive: true });
  try {
    const resultado = await autenticarCredencialCentral({ empresaSlug: "cualquiera", usuarioLocalId: 1, password: "cualquiera", controlDbPath: controlDbPathDirectorio });
    assertEqual(resultado.ok, false, "control DB inaccesible debe fallar");
    assertSame(resultado.errorCode, "CONTROL_DB_INACCESIBLE", "debe reportar CONTROL_DB_INACCESIBLE, distinto de CONTROL_DB_AUSENTE y de CONTROL_DB_QUERY_ERROR");
    if (JSON.stringify(resultado).toLowerCase().includes("password")) throw new Error("CONTROL_DB_INACCESIBLE no debe mencionar password en su serializacion");
  } finally {
    fs.rmSync(controlDbPathDirectorio, { recursive: true, force: true });
  }
}

async function testMT1C2B2AControlDbQueryError() {
  // SQLite real y abrible, pero sin la tabla `empresas`: el OPEN funciona, la query del resolver
  // es la que falla de forma clasificada. Certifica que autenticarCredencialCentral propaga
  // CONTROL_DB_QUERY_ERROR del resolver sin convertirlo en CONTROL_DB_WRITE_ERROR.
  const controlDbPathInvalida = tempDbPath();
  try {
    await runSql(controlDbPathInvalida, "CREATE TABLE dummy_sin_empresas (id INTEGER)");
    const resultado = await autenticarCredencialCentral({ empresaSlug: "cualquiera", usuarioLocalId: 1, password: "cualquiera", controlDbPath: controlDbPathInvalida });
    assertEqual(resultado.ok, false, "control DB estructuralmente invalida debe fallar");
    assertSame(resultado.errorCode, "CONTROL_DB_QUERY_ERROR", "debe reportar CONTROL_DB_QUERY_ERROR, distinto de CONTROL_DB_INACCESIBLE y de CONTROL_DB_WRITE_ERROR");
  } finally {
    fs.rmSync(controlDbPathInvalida, { force: true });
  }
}

async function testMT1C2B2AControlDbWriteErrorRollback() {
  // Control plane temporal 100% valido (empresa+central+membership resuelven correctamente), con
  // un TRIGGER temporal BEFORE UPDATE ON usuarios que aborta cualquier UPDATE real. Certifica que
  // un fallo de escritura strictamente posterior a una resolucion exitosa se clasifica como
  // CONTROL_DB_WRITE_ERROR (no CREDENCIAL_INVALIDA, no QUERY_ERROR) y que el ROLLBACK es real: la
  // fila de usuarios queda byte-a-byte igual a como estaba antes del intento, incluido
  // actualizado_en. El trigger vive unicamente en esta DB temporal.
  const controlDbPath = tempDbPath();
  try {
    const controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
    const empresaSlug = `sec-writeerr-${Date.now()}-${Math.random().toString(16).slice(2)}`;
    const empresa = await registrarEmpresa(controlDb, { slug: empresaSlug, nombre: "Security Write Error Test", dbPath: "guernica.db" });
    const passwordReal = "ClaveCorrectaWriteErr1";
    const hash = await bcrypt.hash(passwordReal, 10);
    const central = await crearUsuarioCentral(controlDb, {
      nombre: "Central Write Error", usuarioReferencia: "central-writeerr", passwordHash: hash, activo: 1
    });
    await crearMembership(controlDb, { usuarioId: central.id, empresaId: empresa.id, usuarioLocalId: 710, rol: "colaborador", activo: 1 });
    const antes = await getControlQuery(
      controlDb, "SELECT intentos_fallidos, bloqueado_hasta, ultimo_acceso, password_hash, actualizado_en FROM usuarios WHERE id = ?", [central.id]
    );
    await runControlQuery(
      controlDb,
      "CREATE TRIGGER trg_test_bloquea_update_usuarios BEFORE UPDATE ON usuarios BEGIN SELECT RAISE(ABORT, 'forzado por test HARDEN'); END"
    );
    await closeControlDb(controlDb);
    await esperarNuevoSegundo();

    const falloWrong = await autenticarCredencialCentral({ empresaSlug, usuarioLocalId: 710, password: "Incorrecta", controlDbPath });
    assertEqual(falloWrong.ok, false, "un UPDATE bloqueado por trigger debe fallar");
    assertSame(falloWrong.errorCode, "CONTROL_DB_WRITE_ERROR", "debe reportar CONTROL_DB_WRITE_ERROR, no CREDENCIAL_INVALIDA ni QUERY_ERROR");
    if (Object.prototype.hasOwnProperty.call(falloWrong, "password_hash")) throw new Error("CONTROL_DB_WRITE_ERROR no debe exponer password_hash");

    const falloSuccess = await autenticarCredencialCentral({ empresaSlug, usuarioLocalId: 710, password: passwordReal, controlDbPath });
    assertEqual(falloSuccess.ok, false, "un UPDATE de exito bloqueado por trigger tambien debe fallar, nunca reportar autenticacion exitosa sin persistir");
    assertSame(falloSuccess.errorCode, "CONTROL_DB_WRITE_ERROR", "debe reportar CONTROL_DB_WRITE_ERROR tambien en el camino de password correcta");

    const controlDbVerif = await bootstrapControlDb(controlDbPath, { seed: false });
    try {
      const despues = await getControlQuery(
        controlDbVerif, "SELECT intentos_fallidos, bloqueado_hasta, ultimo_acceso, password_hash, actualizado_en FROM usuarios WHERE id = ?", [central.id]
      );
      assertEqual(Number(despues.intentos_fallidos), Number(antes.intentos_fallidos), "intentos_fallidos debe quedar SIN CAMBIOS tras rollback real");
      assertSame(despues.bloqueado_hasta, antes.bloqueado_hasta, "bloqueado_hasta debe quedar SIN CAMBIOS tras rollback real");
      assertSame(despues.ultimo_acceso, antes.ultimo_acceso, "ultimo_acceso debe quedar SIN CAMBIOS tras rollback real");
      assertSame(despues.password_hash, antes.password_hash, "password_hash debe quedar SIN CAMBIOS tras rollback real");
      assertSame(despues.actualizado_en, antes.actualizado_en, "actualizado_en debe quedar SIN CAMBIOS tras rollback real (el UPDATE nunca se confirmo)");
    } finally {
      await closeControlDb(controlDbVerif);
    }
  } finally {
    fs.rmSync(controlDbPath, { force: true });
  }
}

// ==================================================================================
// MT-1C.2B.2B: CUTOVER ATOMICO DE AUTENTICACION -- fixtures y tests
// ==================================================================================
//
// setupCentralFixture: composicion local de helpers ya existentes (registrarEmpresa,
// crearUsuarioCentral, crearMembership) para dejar en UN llamado el escenario minimo que todos
// estos tests necesitan: un control plane temporal con empresa+central+membership resolviendo
// correctamente contra el usuario local "admin" YA sembrado por bootstrapFreshRegisteredTenantDb().
// No reemplaza ni envuelve autenticarCredencialCentral/resolverIdentidadCentralPorLocal -- solo arma
// el estado sobre el que /login (rama central) los invoca de verdad via HTTP.
//
// MT-1D.2B: businessDbPath DEBE venir de bootstrapFreshRegisteredTenantDb() (vive dentro de
// database/, no de os.tmpdir()) -- registra el db_path REAL del fixture (antes un literal
// "guernica.db" que no correspondia a ningun archivo real) y siembra tenant_identity TEST-ONLY
// (INSERT directo, nunca via database/provision-tenant-identity.js) para que el Central Boot
// Identity Gate de backend/server.js encuentre una identidad valida al arrancar.
async function setupCentralFixture({
  businessDbPath,
  localPassword = "LocalDefault123",
  localActivo = 1,
  localRol = "colaborador",
  centralPassword = "CentralDefault123",
  centralActivo = 1,
  empresaActiva = 1,
  membershipActivo = 1,
  membershipRol = "admin",
  sinMembership = false
} = {}) {
  const localHash = await bcrypt.hash(localPassword, 10);
  await runSql(businessDbPath, "UPDATE usuarios SET password = ?, activo = ?, rol = ? WHERE usuario = ?", [localHash, localActivo, localRol, "admin"]);
  const localUser = (await allSql(businessDbPath, "SELECT id FROM usuarios WHERE usuario = ?", ["admin"]))[0];

  const controlDbPath = tempDbPath();
  const controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
  const empresaSlug = `mt1c2b2b-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  const empresa = await registrarEmpresa(controlDb, { slug: empresaSlug, nombre: "MT1C2B2B Cutover Test", dbPath: path.basename(businessDbPath), activa: empresaActiva });
  const centralHash = await bcrypt.hash(centralPassword, 10);
  const central = await crearUsuarioCentral(controlDb, {
    nombre: "MT1C2B2B Central", usuarioReferencia: "mt1c2b2b-central", passwordHash: centralHash, activo: centralActivo
  });
  const membership = sinMembership ? null : await crearMembership(controlDb, {
    usuarioId: central.id, empresaId: empresa.id, usuarioLocalId: localUser.id, rol: membershipRol, activo: membershipActivo
  });
  await closeControlDb(controlDb);
  await insertarTenantIdentityTest(businessDbPath, empresa.id, empresaSlug);

  return { controlDbPath, empresaSlug, empresa, central, membership, localUserId: localUser.id, localPassword, centralPassword };
}

function extraEnvCentral(fixture) {
  return { ATLAS_AUTH_MODE: "central", ATLAS_EMPRESA_SLUG: fixture.empresaSlug, ATLAS_CONTROL_DB_PATH: fixture.controlDbPath };
}

// Deteccion deterministica de "el servidor no debe quedar operativo" (config invalida). No
// reutiliza waitForServer (que espera hasta 12s asumiendo que el server DEBERIA arrancar) --
// aca el contrato es el opuesto: process.exit(1) sincrono ANTES de app.listen(), asi que el
// proceso hijo debe terminar casi de inmediato. Un timeout esperando el exit es en si mismo la
// senal de que el fail-closed NO ocurrio.
async function esperarStartupFallido(dbPath, extraEnv, timeoutMs = 8000) {
  // Mismo criterio hermetico que withServer: no heredar ATLAS_* del proceso padre por defecto.
  const baseEnv = { ...process.env };
  delete baseEnv.ATLAS_AUTH_MODE;
  delete baseEnv.ATLAS_EMPRESA_SLUG;
  delete baseEnv.ATLAS_CONTROL_DB_PATH;
  delete baseEnv.ATLAS_TENANCY_MODE;
  const child = spawn(process.execPath, ["backend/server.js"], {
    cwd: ROOT,
    env: { ...baseEnv, GUERNICA_DB_PATH: dbPath, ...extraEnv },
    stdio: ["ignore", "pipe", "pipe"]
  });
  let logs = "";
  child.stdout.on("data", (chunk) => { logs += chunk.toString(); });
  child.stderr.on("data", (chunk) => { logs += chunk.toString(); });

  const salida = await new Promise((resolve) => {
    const timer = setTimeout(() => resolve(null), timeoutMs);
    child.once("exit", (code) => {
      clearTimeout(timer);
      resolve({ code });
    });
  });

  if (!salida) {
    if (!child.killed) child.kill("SIGKILL");
    throw new Error(`El servidor deberia haber fallado el startup (fail-closed) pero sigue vivo tras ${timeoutMs}ms.\n${logs}`);
  }
  if (salida.code === 0) {
    throw new Error(`El servidor deberia fallar el startup con exit code != 0, salio con 0 (no fail-closed).\n${logs}`);
  }
  return { code: salida.code, logs };
}

async function testMT1C2B2BLegacyDefaultSigueIdentico() {
  const dbPath = bootstrapFreshTestDb();
  try {
    await withServer(dbPath, async (baseUrl) => {
      const { response, data } = await requestJson(baseUrl, "POST", "/login", { usuario: "admin", password: "admin123" }, null);
      assertEqual(response.status, 200, "login legacy sin ATLAS_AUTH_MODE debe seguir funcionando identico");
      const token = data.token;

      const sesionRow = (await allSql(dbPath, "SELECT auth_mode, central_id, membership_id, empresa_id FROM sesiones WHERE token = ?", [token]))[0];
      assertSame(sesionRow.auth_mode, "legacy", "sesion sin ATLAS_AUTH_MODE debe quedar auth_mode='legacy' (default)");
      if (sesionRow.central_id !== null) throw new Error("sesion legacy no debe tener central_id");
      if (sesionRow.membership_id !== null) throw new Error("sesion legacy no debe tener membership_id");
      if (sesionRow.empresa_id !== null) throw new Error("sesion legacy no debe tener empresa_id");

      const protegido = await requestJson(baseUrl, "GET", "/configuracion", null, token);
      assertEqual(protegido.response.status, 200, "endpoint protegido debe aceptar sesion legacy en runtime legacy (default)");
    });
  } finally {
    fs.rmSync(dbPath, { force: true });
  }
}

async function testMT1C2B2BCentralSuccessSesionYEndpoint() {
  const dbPath = bootstrapFreshRegisteredTenantDb();
  let controlDbPath;
  try {
    const fixture = await setupCentralFixture({ businessDbPath: dbPath });
    controlDbPath = fixture.controlDbPath;
    await withServer(dbPath, async (baseUrl) => {
      const { response, data } = await requestJson(baseUrl, "POST", "/login", { usuario: "admin", password: fixture.centralPassword }, null);
      assertEqual(response.status, 200, "login central con password central correcta debe autenticar");
      const token = data.token;

      const sesionRow = (await allSql(dbPath, "SELECT usuario_id, auth_mode, central_id, membership_id, empresa_id, rol FROM sesiones WHERE token = ?", [token]))[0];
      assertSame(sesionRow.auth_mode, "central", "sesion central debe quedar auth_mode='central'");
      assertEqual(sesionRow.usuario_id, fixture.localUserId, "usuario_id de sesion debe ser el ID LOCAL");
      assertEqual(sesionRow.central_id, fixture.central.id, "central_id debe ser el de la identidad central resuelta");
      assertEqual(sesionRow.membership_id, fixture.membership.id, "membership_id debe ser el de la membership resuelta");
      assertEqual(sesionRow.empresa_id, fixture.empresa.id, "empresa_id debe ser el de la empresa resuelta");
      assertSame(sesionRow.rol, "admin", "rol de sesion debe venir de membership");

      if (Object.prototype.hasOwnProperty.call(data, "central_id")) throw new Error("response no debe exponer central_id");
      if (Object.prototype.hasOwnProperty.call(data, "membership_id")) throw new Error("response no debe exponer membership_id");
      if (Object.prototype.hasOwnProperty.call(data, "empresa_id")) throw new Error("response no debe exponer empresa_id");
      if (Object.prototype.hasOwnProperty.call(data, "auth_mode")) throw new Error("response no debe exponer auth_mode");
      if (JSON.stringify(data).toLowerCase().includes("password")) throw new Error("response no debe mencionar password/hash");
      // HARDEN: busqueda de nombres de clave en TODA la serializacion, no solo top-level -- si
      // alguno de estos apareciera anidado dentro de `user` (o en cualquier otro lugar futuro),
      // los hasOwnProperty de arriba no lo detectarian.
      const serializado = JSON.stringify(data);
      for (const clave of ["central_id", "membership_id", "empresa_id", "auth_mode"]) {
        if (serializado.includes(`"${clave}"`)) throw new Error(`response no debe exponer "${clave}" en ninguna parte de la serializacion (top-level ni anidado)`);
      }
      assertEqual(data.user.id, fixture.localUserId, "user.id debe ser LOCAL");
      const clavesUser = Object.keys(data.user).sort();
      assertSame(JSON.stringify(clavesUser), JSON.stringify(["email", "foto_url", "id", "nombre", "rol", "telefono", "usuario"].sort()), "user debe exponer exactamente el shape esperado, sin campos extra");

      const protegido = await requestJson(baseUrl, "GET", "/configuracion", null, token);
      assertEqual(protegido.response.status, 200, "endpoint protegido debe aceptar sesion central en runtime central");
    }, extraEnvCentral(fixture));
  } finally {
    limpiarTenantTestDb(dbPath);
    if (controlDbPath) fs.rmSync(controlDbPath, { force: true });
  }
}

