      "sqlite3.Database.prototype.backup = function (destPath, initCb) {",
      "  const emitter = new EventEmitter();",
      "  emitter.step = (pages, cb) => { setImmediate(() => cb(null, true)); };",
      "  emitter.finish = (cb) => {",
