// Ejecuta funciones REALES de server.js aisladas, sin arrancar servidor ni agregar endpoints.
// Permite inducir contexto ausente/corrupto y resultado central inconsistente, imposibles desde Host sano.
function mt1f4AuthAislada(overrides = {}) {
  const fuente = fs.readFileSync(path.join(ROOT, "backend/server.js"), "utf8");
  const nombres = ["empresaAuthDelRequest", "rechazarNoAutenticado", "requireAuth", "loginCentral", "responderFalloAuthCentral"];
  const funciones = nombres.map((nombre) => {
    const match = fuente.match(new RegExp(`^(?:async )?function ${nombre}\\([^]*?^\\}`, "m"));
    if (!match) throw new Error(`Funcion real no encontrada: ${nombre}`);
    return match[0];
  }).join("\n");
  const prohibido = () => { throw new Error("Acceso fuera del contexto autorizado"); };
  return require("vm").runInNewContext(`${funciones}\n({ ${nombres.join(", ")} })`, {
    ATLAS_TENANCY_MODE: "multi", TENANCY_MODES, ATLAS_AUTH_MODE: "central", ATLAS_EMPRESA_SLUG: "fallback-prohibido",
    PREAUTH_UNIFORME: true, getTenantContext: () => null,
    responderNoAutenticado: require("../backend/tenantRequestMiddleware").responderNoAutenticado,
    getQuery: prohibido, runQuery: prohibido, autenticarCredencialCentral: prohibido, revalidarSesionCentral: prohibido,
    esRutaPublicaSinAuth: () => false, process: { env: { GUERNICA_DB_PATH: "fallback-prohibido" } }, console,
    ...overrides
  });
}

async function testMT1F4MultiSinContextoNoFallback() {
  const respuesta = () => ({ statusCode: 200, status(code) { this.statusCode = code; return this; }, json(body) { this.body = body; return this; } });
  for (const contexto of [null, {}, { empresaId: 0, empresaSlug: "a" }, { empresaId: 1.5, empresaSlug: "a" }, { empresaId: "1", empresaSlug: "a" }, { empresaId: 1, empresaSlug: "" }, { empresaId: 1, empresaSlug: " a " }]) {
    const auth = mt1f4AuthAislada({ getTenantContext: () => contexto });
    assertSame(auth.empresaAuthDelRequest(), null, "contexto invalido no toma env/body/ultimo tenant");
    const loginRes = respuesta();
    await auth.loginCentral({ body: { empresaSlug: "fallback-prohibido" } }, loginRes, { usuario: "admin", password: "123" });
    assertEqual(loginRes.statusCode, 401, "sin contexto login rechaza antes de DB/Control");
    const authRes = respuesta();
    await auth.requireAuth({ path: "/configuracion", headers: { authorization: "Bearer valido" } }, authRes, () => { throw new Error("next no autorizado"); });
    assertEqual(authRes.statusCode, 401, "sin contexto requireAuth rechaza antes de DB/Control");
  }
  let autenticaciones = 0;
  const auth = mt1f4AuthAislada({
    getTenantContext: () => ({ empresaId: 1, empresaSlug: "a" }),
    getQuery: async () => ({ id: 7 }),
    autenticarCredencialCentral: async ({ empresaSlug, usuarioLocalId }) => {
      autenticaciones += 1;
      assertSame(empresaSlug, "a", "se pasa slug ALS");
      assertEqual(usuarioLocalId, 7, "se pasa ID local");
      return { ok: true, empresa: { id: 2 } };
    }
  });
  const res = respuesta();
  await auth.loginCentral({}, res, { usuario: "admin", password: "123" });
  assertEqual(autenticaciones, 1, "resultado central inconsistente ejercitado");
  assertEqual(res.statusCode, 401, "empresa distinta no emite token ni escribe sesion");
}

async function testMT1F4MultiLoginNoEnumeraMembership() {
  await mt1f4ConEscenario(async ({ escenario, a, b, pedir }) => {
    const respuestas = [];
    respuestas.push(await pedir(a, "POST", "/login", { usuario: "no-existe-f4", password: a.password }));
    respuestas.push(await pedir(b, "POST", "/login", { usuario: "admin", password: a.password }));
    await runSql(escenario.controlDbPath, "UPDATE usuario_empresas SET activo = 0 WHERE id = ?", [a.membership.id]);
    respuestas.push(await pedir(a, "POST", "/login", { usuario: "admin", password: a.password }));
    await runSql(escenario.controlDbPath, "UPDATE usuario_empresas SET activo = 1 WHERE id = ?", [a.membership.id]);
    await runSql(escenario.controlDbPath, "UPDATE usuarios SET activo = 0 WHERE id = ?", [a.central.id]);
    respuestas.push(await pedir(a, "POST", "/login", { usuario: "admin", password: a.password }));
    await runSql(escenario.controlDbPath, "UPDATE usuarios SET activo = 1 WHERE id = ?", [a.central.id]);
    respuestas.push(await pedir(a, "POST", "/login", { usuario: "admin", password: "incorrecta" }));
    const firma = (r) => JSON.stringify([r.status, r.contentType, r.texto]);
    for (const r of respuestas) {
      assertSame(mt1f3EsNoAutenticado(r), true, "login anonimo generico sin token");
      assertSame(firma(r), firma(respuestas[0]), "mismo 401, Content-Type y body");
    }
    assertEqual((await allSql(a.dbPath, "SELECT * FROM sesiones")).length, 0, "ningun fallo emite sesion A");
    assertEqual((await allSql(b.dbPath, "SELECT * FROM sesiones")).length, 0, "ningun fallo emite sesion B");
    await runSql(escenario.controlDbPath, "UPDATE usuarios SET intentos_fallidos = 99, bloqueado_hasta = ? WHERE id = ?", [new Date(Date.now() + 600000).toISOString(), a.central.id]);
    assertEqual((await pedir(a, "POST", "/login", { usuario: "admin", password: a.password })).status, 429, "lockout central conserva 429");
    await runSql(escenario.controlDbPath, "ALTER TABLE usuario_empresas RENAME TO membresias_indisponibles_f4");
    const operacional = await pedir(a, "POST", "/login", { usuario: "admin", password: a.password });
    assertEqual(operacional.status, 503, "error operacional Control conserva 503");
    assertSame(operacional.json.message, "Servicio de autenticacion no disponible", "503 no filtra detalles Control");
  }, { membershipB: false });
}

// ====================================================================================================
// MT-1F5A: la cola de ingreso fisico de stock (backend/server.js) pasa de UNA sola Promise
// process-global a una lane por tenant (Map<key, Promise>). Los tests extraen el codigo REAL de
// server.js via vm (misma tecnica que mt1f4AuthAislada) en vez de reimplementar la logica, para
// probar el comportamiento shippeado, no una copia.
// ====================================================================================================
function mt1f5aColaAislada(overrides = {}) {
  const fuente = fs.readFileSync(path.join(ROOT, "backend/server.js"), "utf8");
  const constantes = fuente.match(/^const stockIngresoFisicoQueues = new Map\(\);\r?\nconst STOCK_INGRESO_FISICO_QUEUE_KEY_SINGLE = "single";\r?$/m);
  if (!constantes) throw new Error("Constantes reales de la cola de stock no encontradas en server.js");
  const nombresFn = ["resolverStockIngresoFisicoQueueKey", "encolarIngresoFisicoStock"];
  const funciones = nombresFn.map((nombre) => {
    const match = fuente.match(new RegExp(`^(?:async )?function ${nombre}\\([^]*?^\\}`, "m"));
    if (!match) throw new Error(`Funcion real no encontrada: ${nombre}`);
    return match[0];
  }).join("\n");
  const bloque = `${constantes[0]}\n${funciones}`;
  const nombres = ["stockIngresoFisicoQueues", "resolverStockIngresoFisicoQueueKey", "encolarIngresoFisicoStock"];
  return require("vm").runInNewContext(`${bloque}\n({ ${nombres.join(", ")} })`, {
    ATLAS_TENANCY_MODE: "multi",
    TENANCY_MODES,
    getTenantContext: () => null,
    ...overrides
  });
}

async function testMT1F5AColaStockSeParticionaPorTenant() {
  let contextoActual = null;
  const { encolarIngresoFisicoStock } = mt1f5aColaAislada({ getTenantContext: () => contextoActual });
  const eventos = [];

  let liberarA;
  const gateA = new Promise((resolve) => { liberarA = resolve; });

  contextoActual = { empresaId: 501 };
  const promesaA = encolarIngresoFisicoStock(async () => {
    eventos.push("A-inicio");
    await gateA;
    eventos.push("A-fin");
    return "A";
  });

  contextoActual = { empresaId: 502 };
  const promesaB = encolarIngresoFisicoStock(async () => {
    eventos.push("B-inicio");
    eventos.push("B-fin");
    return "B";
  });

  const resultadoB = await promesaB;
  assertSame(resultadoB, "B", "B (tenant 502) debe completar sin esperar a A (tenant 501)");
  assertSame(eventos.includes("A-fin"), false, "A debe seguir pendiente en su gate cuando B ya termino: sin head-of-line blocking cruzado");
  assertSame(JSON.stringify(eventos), JSON.stringify(["A-inicio", "B-inicio", "B-fin"]), "orden de eventos: B se ejecuta y termina integramente mientras A sigue bloqueado en su propio gate");

  liberarA();
  const resultadoA = await promesaA;
  assertSame(resultadoA, "A", "A completa recien al liberar su gate, en su propia lane");
  assertSame(JSON.stringify(eventos), JSON.stringify(["A-inicio", "B-inicio", "B-fin", "A-fin"]), "orden final: A termina despues, sin haber afectado a B");
}

async function testMT1F5AMismoTenantConservaSerializacion() {
  const contexto = { empresaId: 601 };
  const { encolarIngresoFisicoStock } = mt1f5aColaAislada({ getTenantContext: () => contexto });
  const eventos = [];

  let liberarA1;
  const gateA1 = new Promise((resolve) => { liberarA1 = resolve; });
  const promesaA1 = encolarIngresoFisicoStock(async () => {
    eventos.push("A1-inicio");
    await gateA1;
    eventos.push("A1-fin");
    return "A1";
  });
  const promesaA2 = encolarIngresoFisicoStock(async () => {
    eventos.push("A2-inicio");
    return "A2";
  });

  // Evidencia primaria: la dependencia estructural de la cadena de promesas (A2 solo puede
  // iniciar despues de que A1 asiente, sea cual sea el timing real). El delay es solo una
  // confirmacion adicional, no la prueba.
  await delay(30);
  assertSame(JSON.stringify(eventos), JSON.stringify(["A1-inicio"]), "A2 no debe iniciar mientras A1 (mismo tenant) sigue pendiente en su gate");

  liberarA1();
  const [resultadoA1, resultadoA2] = await Promise.all([promesaA1, promesaA2]);
  assertSame(resultadoA1, "A1", "A1 completa tras liberar su gate");
  assertSame(resultadoA2, "A2", "A2 completa despues de A1");
  assertSame(JSON.stringify(eventos), JSON.stringify(["A1-inicio", "A1-fin", "A2-inicio"]), "orden estricto: A1 termina antes de que A2 inicie, mismo tenant sigue serializado FIFO");

  // Una operacion rechazada no debe envenenar la lane: la siguiente operacion del MISMO tenant
  // debe seguir ejecutandose con normalidad.
  let capturado = null;
  try {
    await encolarIngresoFisicoStock(async () => { throw new Error("falla deliberada A3"); });
  } catch (error) {
    capturado = error;
  }
  assertSame(capturado?.message, "falla deliberada A3", "A3 rechaza propagando el error real del callback");

  const resultadoA4 = await encolarIngresoFisicoStock(async () => "A4");
  assertSame(resultadoA4, "A4", "una operacion posterior del MISMO tenant sigue ejecutandose tras un fallo previo: la lane no queda envenenada");
}

async function testMT1F5AColaPreservaContextoTenant() {
  const escenario = await mt1f1CrearEscenario(["a", "b"]);
  try {
    const [resultadoA, resultadoB] = await Promise.all([
      mt1f1Resolver(escenario.tenants[0], escenario.controlDbPath),
      mt1f1Resolver(escenario.tenants[1], escenario.controlDbPath)
    ]);
    assertSame(resultadoA.ok, true, "handle A debe resolver");
    assertSame(resultadoB.ok, true, "handle B debe resolver");
    const handleA = resultadoA.handle;
    const handleB = resultadoB.handle;

    // getTenantContext REAL (no mockeado): probamos que la cola vm-extraida, corriendo dentro de
    // runWithTenantHandle REAL, ve el contexto ALS verdadero -- no una copia de test.
    const { encolarIngresoFisicoStock } = mt1f5aColaAislada({ getTenantContext });

    const valorA = `f5a-marca-a-${Date.now()}`;
    const valorB = `f5a-marca-b-${Date.now()}`;

    const promesaA = runWithTenantHandle(handleA, () => encolarIngresoFisicoStock(async () => {
      const contexto = getTenantContext();
      assertEqual(contexto.empresaId, escenario.tenants[0].empresa.id, "callback encolado desde A ve el empresaId de A dentro de la lane");
      await dbRunQuery("INSERT OR REPLACE INTO configuracion_global (clave, valor, seccion, actualizado_en) VALUES ('f5a_marca_disponible', ?, 'test', datetime('now'))", [JSON.stringify(valorA)]);
      return "A";
    }));

    const promesaB = runWithTenantHandle(handleB, () => encolarIngresoFisicoStock(async () => {
      const contexto = getTenantContext();
      assertEqual(contexto.empresaId, escenario.tenants[1].empresa.id, "callback encolado desde B ve el empresaId de B dentro de la lane");
      await dbRunQuery("INSERT OR REPLACE INTO configuracion_global (clave, valor, seccion, actualizado_en) VALUES ('f5a_marca_disponible', ?, 'test', datetime('now'))", [JSON.stringify(valorB)]);
      return "B";
    }));

    const [okA, okB] = await Promise.all([promesaA, promesaB]);
    assertSame(okA, "A", "operacion A completa dentro de su propia lane/contexto");
    assertSame(okB, "B", "operacion B completa dentro de su propia lane/contexto");

    const filaA = (await allSql(escenario.tenants[0].dbPath, "SELECT valor FROM configuracion_global WHERE clave = 'f5a_marca_disponible'"))[0];
    const filaB = (await allSql(escenario.tenants[1].dbPath, "SELECT valor FROM configuracion_global WHERE clave = 'f5a_marca_disponible'"))[0];
    assertSame(JSON.parse(filaA.valor), valorA, "la DB fisica de A tiene el valor escrito por el callback A -- prueba empirica, no solo teoria de ALS");
    assertSame(JSON.parse(filaB.valor), valorB, "la DB fisica de B tiene el valor escrito por el callback B, nunca el de A: sin cruce de escritura entre lanes");
  } finally {
    await mt1f1Limpiar(escenario);
  }
}

async function testMT1F5AMultiSinContextoNoFallback() {
  const contextosInvalidos = [null, {}, { empresaId: 0 }, { empresaId: -1 }, { empresaId: 1.5 }, { empresaId: "1" }];
  for (const contexto of contextosInvalidos) {
    let ejecutado = false;
    const { encolarIngresoFisicoStock } = mt1f5aColaAislada({ ATLAS_TENANCY_MODE: "multi", getTenantContext: () => contexto });
    let error = null;
    try {
      await encolarIngresoFisicoStock(async () => { ejecutado = true; return "no-debe-pasar"; });
    } catch (err) {
      error = err;
    }
    assertSame(ejecutado, false, `contexto invalido ${JSON.stringify(contexto)}: el callback NO debe ejecutarse`);
    assertSame(error !== null, true, `contexto invalido ${JSON.stringify(contexto)}: debe fallar cerrado (rechazar), nunca caer a una lane global/SINGLE`);
  }

  // Contexto multi valido SI debe ejecutar (no es que la cola este rota en general).
  const { encolarIngresoFisicoStock: encolarValido } = mt1f5aColaAislada({ ATLAS_TENANCY_MODE: "multi", getTenantContext: () => ({ empresaId: 777, empresaSlug: "ok" }) });
  const resultadoValido = await encolarValido(async () => "ejecutado");
  assertSame(resultadoValido, "ejecutado", "un contexto multi valido SI ejecuta el callback normalmente");

  // Modo single: key estable, getTenantContext NUNCA se consulta (short-circuit antes de leerlo).
  const prohibido = () => { throw new Error("getTenantContext no debe consultarse en modo single"); };
  const { encolarIngresoFisicoStock: encolarSingle, stockIngresoFisicoQueues: colasSingle } = mt1f5aColaAislada({ ATLAS_TENANCY_MODE: "single", getTenantContext: prohibido });
  const resultadoSingle = await encolarSingle(async () => "single-ok");
  assertSame(resultadoSingle, "single-ok", "modo single ejecuta con su key estable sin tocar getTenantContext");
  assertEqual(colasSingle.size, 0, "tras asentarse, la lane single tambien se limpia del Map (sin fuga)");
}

// ====================================================================================================
// MT-1F5B: almacenamiento de uploads tenant-aware. Los helpers de fixture SOLO escriben bajo
// uploads/tenants/<empresaId>/... (namespace que no existia antes de F5B) o bajo un archivo LEGACY con
// nombre inequivocamente de test (mt1f5b-...) -- jamas tocan ninguno de los 61 archivos reales. Todo
// fixture se limpia deterministicamente en finally.
// ====================================================================================================
function mt1f5bRutaTenant(empresaId, categoria, filename) {
  return path.join(ROOT, "uploads", "tenants", String(empresaId), categoria, filename);
}
function mt1f5bSembrarTenant(empresaId, categoria, filename, contenido) {
  const ruta = mt1f5bRutaTenant(empresaId, categoria, filename);
  fs.mkdirSync(path.dirname(ruta), { recursive: true });
  fs.writeFileSync(ruta, contenido, "utf8");
  return ruta;
}
function mt1f5bLimpiarTenant(empresaId) {
  fs.rmSync(path.join(ROOT, "uploads", "tenants", String(empresaId)), { recursive: true, force: true });
}
function mt1f5bRutaLegacy(categoria, filename) {
  return path.join(ROOT, "uploads", categoria, filename);
}
function mt1f5bSembrarLegacy(categoria, filename, contenido) {
  const ruta = mt1f5bRutaLegacy(categoria, filename);
  fs.mkdirSync(path.dirname(ruta), { recursive: true });
  fs.writeFileSync(ruta, contenido, "utf8");
  return ruta;
}
function mt1f5bLimpiarLegacy(categoria, filename) {
  fs.rmSync(mt1f5bRutaLegacy(categoria, filename), { force: true });
}
function mt1f5bNombreTest(etiqueta) {
  return `mt1f5b-test-${etiqueta}-${Date.now()}-${Math.random().toString(16).slice(2, 8)}.txt`;
}
// fetch() trata "Host" como forbidden header y lo ignora silenciosamente (manda el Host real de la
// conexion, no el que uno pide) -- por eso estos tests reusan mt1f3Pedir (http.request crudo, mismo
// mecanismo ya probado por toda la suite MT-1F3/F4/F5A) en vez de fetch().
async function mt1f5bGetTexto(port, ruta, host) {
  const respuesta = await mt1f3Pedir(port, { host, ruta });
  return { status: respuesta.status, texto: respuesta.texto, contentType: respuesta.contentType };
}

async function testMT1F5BMultiWriteUsaRootTenant() {
  const { crearTenantUploadStorage, CATEGORIAS_VALIDAS } = require("../backend/tenantUploadStorage");
  const uploadsRoot = path.join(ROOT, "uploads");
  let contexto = null;
  const storage = crearTenantUploadStorage({ tenancyMode: "multi", getTenantContext: () => contexto, uploadsRoot });

  const tenants = [
    { empresaId: 910001, empresaSlug: "mt1f5b-tenant-a" },
    { empresaId: 910002, empresaSlug: "mt1f5b-tenant-b" },
    { empresaId: 1, empresaSlug: "guernica" }
  ];
  for (const tenant of tenants) {
    contexto = tenant;
    for (const categoria of CATEGORIAS_VALIDAS) {
      const destino = storage.resolverDestinoEscritura({ categoria, filename: "archivo-test.png" });
      assertSame(Boolean(destino), true, `destino de escritura valido: empresaId=${tenant.empresaId} categoria=${categoria}`);
      const relativo = path.relative(path.join(uploadsRoot, "tenants"), destino.ruta);
      const segmentos = relativo.split(path.sep);
      assertSame(segmentos[0], String(tenant.empresaId), `segmento de empresa exacto (empresaId=${tenant.empresaId})`);
      assertSame(segmentos[1], categoria, "segmento de categoria exacto");
      assertSame(segmentos[2], "archivo-test.png", "segmento de filename exacto");
      assertSame(destino.ruta.startsWith(uploadsRoot + path.sep + "tenants" + path.sep), true, "jamas la raiz legacy compartida como destino de escritura en multi (incluye Guernica)");
    }
  }
}

async function testMT1F5BMismoPathAisladoEntreTenants() {
  const { crearTenantUploadStorage } = require("../backend/tenantUploadStorage");
  const uploadsRoot = fs.mkdtempSync(path.join(os.tmpdir(), "mt1f5b-aislado-"));
  try {
    let contexto = { empresaId: 501, empresaSlug: "tenant-a" };
    const storage = crearTenantUploadStorage({ tenancyMode: "multi", getTenantContext: () => contexto, uploadsRoot });

    const destinoA = storage.resolverDestinoEscritura({ categoria: "productos", filename: "mismo.png" });
    fs.mkdirSync(destinoA.directorio, { recursive: true });
    fs.writeFileSync(destinoA.ruta, "CONTENIDO-A");

    contexto = { empresaId: 502, empresaSlug: "tenant-b" };
    const destinoB = storage.resolverDestinoEscritura({ categoria: "productos", filename: "mismo.png" });
    fs.mkdirSync(destinoB.directorio, { recursive: true });
    fs.writeFileSync(destinoB.ruta, "CONTENIDO-B");

    assertSame(destinoA.ruta !== destinoB.ruta, true, "misma categoria+filename produce rutas fisicas distintas para A y B (misma forma de URL externa: productos/mismo.png)");

    contexto = { empresaId: 501, empresaSlug: "tenant-a" };
    const candidatosA = storage.resolverCandidatosLectura({ categoria: "productos", filename: "mismo.png" });
    assertEqual(candidatosA.length, 1, "A no tiene fallback legacy (no es guernica)");
    assertSame(fs.readFileSync(candidatosA[0], "utf8"), "CONTENIDO-A", "lectura bajo contexto A produce bytes de A");

    contexto = { empresaId: 502, empresaSlug: "tenant-b" };
    const candidatosB = storage.resolverCandidatosLectura({ categoria: "productos", filename: "mismo.png" });
    assertSame(fs.readFileSync(candidatosB[0], "utf8"), "CONTENIDO-B", "lectura bajo contexto B produce bytes de B, nunca los de A");
  } finally {
    fs.rmSync(uploadsRoot, { recursive: true, force: true });
  }
}

async function testMT1F5BHostANoLeeArchivoB() {
  const escenario = await mt1f1CrearEscenario(["a", "b"]);
  const decoyPath = tempDbPath();
  const [tenantA, tenantB] = escenario.tenants;
  const nombreArchivo = mt1f5bNombreTest("solo-b");
  try {
    mt1f5bSembrarTenant(tenantB.empresa.id, "productos", nombreArchivo, "SOLO-B");
    await mt1f3ConServidor(mt1f3EntornoMulti(escenario, decoyPath), async (servidor) => {
      // control: B lee su propio archivo.
      const propio = await mt1f5bGetTexto(servidor.port, `/uploads/productos/${nombreArchivo}`, mt1f3Host(tenantB));
      assertEqual(propio.status, 200, "B lee su propio archivo (control positivo)");
      assertSame(propio.texto, "SOLO-B", "B recibe sus propios bytes");

      // A no tiene ese archivo en su propia raiz: debe fallar cerrado, sin buscar en B ni en legacy.
      const viaA = await mt1f5bGetTexto(servidor.port, `/uploads/productos/${nombreArchivo}`, mt1f3Host(tenantA));
      assertEqual(viaA.status, 404, "A no puede leer un archivo que solo existe en la raiz de B");
      assertSame(viaA.texto.includes("SOLO-B"), false, "la respuesta a A no filtra el contenido de B");
    });
  } finally {
    mt1f5bLimpiarTenant(tenantA.empresa.id);
    mt1f5bLimpiarTenant(tenantB.empresa.id);
    await mt1f1Limpiar(escenario);
  }
}

async function testMT1F5BPublicProductosYLogoSinAuth() {
  const escenario = await mt1f1CrearEscenario(["a"]);
  const decoyPath = tempDbPath();
  const [tenantA] = escenario.tenants;
  const nombreProducto = mt1f5bNombreTest("producto-publico");
  const nombreLogo = mt1f5bNombreTest("logo-publico");
  try {
    mt1f5bSembrarTenant(tenantA.empresa.id, "productos", nombreProducto, "IMAGEN-PRODUCTO-PUBLICA");
    mt1f5bSembrarTenant(tenantA.empresa.id, "configuracion", nombreLogo, "IMAGEN-LOGO-PUBLICA");
    await mt1f3ConServidor(mt1f3EntornoMulti(escenario, decoyPath), async (servidor) => {
      const port = servidor.port;
      const producto = await mt1f5bGetTexto(port, `/uploads/productos/${nombreProducto}`, mt1f3Host(tenantA));
      assertEqual(producto.status, 200, "producto se sirve sin Authorization en central+multi");
      assertSame(producto.texto, "IMAGEN-PRODUCTO-PUBLICA", "bytes correctos de producto");

      const logo = await mt1f5bGetTexto(port, `/uploads/configuracion/${nombreLogo}`, mt1f3Host(tenantA));
      assertEqual(logo.status, 200, "logo se sirve sin Authorization en central+multi");
      assertSame(logo.texto, "IMAGEN-LOGO-PUBLICA", "bytes correctos de logo");

      // el storefront publico sigue alcanzable y no requiere auth: la forma de URL /uploads/... que
      // devuelve (si el producto la tuviera) no cambia -- eso ya lo prueban los tests de arriba.
      const storefront = await mt1f5bGetTexto(port, "/tienda/publica/productos", mt1f3Host(tenantA));
      assertEqual(storefront.status, 200, "el storefront publico sigue respondiendo sin auth");
      const logoInfo = await mt1f5bGetTexto(port, "/tienda/publica", mt1f3Host(tenantA));
      assertEqual(logoInfo.status, 200, "GET /tienda/publica (nombre+logo_url) sigue respondiendo sin auth");
    });
  } finally {
    mt1f5bLimpiarTenant(tenantA.empresa.id);
    await mt1f1Limpiar(escenario);
  }
}

async function testMT1F5BUsuariosClientesSinBearerSiguenSirviendo() {
  const escenario = await mt1f1CrearEscenario(["a"]);
  const decoyPath = tempDbPath();
  const [tenantA] = escenario.tenants;
  const nombreUsuario = mt1f5bNombreTest("avatar-usuario");
  const nombreCliente = mt1f5bNombreTest("foto-cliente");
  try {
    mt1f5bSembrarTenant(tenantA.empresa.id, "usuarios", nombreUsuario, "AVATAR-USUARIO");
    mt1f5bSembrarTenant(tenantA.empresa.id, "clientes", nombreCliente, "FOTO-CLIENTE");
    await mt1f3ConServidor(mt1f3EntornoMulti(escenario, decoyPath), async (servidor) => {
      const port = servidor.port;
      // Deliberadamente SIN Authorization: user-menu.js/perfil.html/clientes.html usan <img src>/
      // background-image nativos, que el navegador jamas manda con Bearer (F5B no cambia eso).
      const usuario = await mt1f5bGetTexto(port, `/uploads/usuarios/${nombreUsuario}`, mt1f3Host(tenantA));
      assertEqual(usuario.status, 200, "avatar de usuario se sirve sin Authorization dentro del tenant correcto");
      assertSame(usuario.texto, "AVATAR-USUARIO", "bytes correctos de avatar");

      const cliente = await mt1f5bGetTexto(port, `/uploads/clientes/${nombreCliente}`, mt1f3Host(tenantA));
      assertEqual(cliente.status, 200, "foto de cliente se sirve sin Authorization dentro del tenant correcto");
      assertSame(cliente.texto, "FOTO-CLIENTE", "bytes correctos de foto de cliente");
    });
  } finally {
    mt1f5bLimpiarTenant(tenantA.empresa.id);
    await mt1f1Limpiar(escenario);
  }
}

async function testMT1F5BMultiSinContextoNoFallback() {
  const escenario = await mt1f1CrearEscenario(["a"]);
  const decoyPath = tempDbPath();
  const nombreLegacy = mt1f5bNombreTest("cebo-legacy");
  try {
    mt1f5bSembrarLegacy("productos", nombreLegacy, "CEBO-LEGACY-NO-DEBE-SERVIRSE");
    await mt1f3ConServidor(mt1f3EntornoMulti(escenario, decoyPath), async (servidor) => {
      const port = servidor.port;
      // Host sin candidato de tenant resuelto (tenant desconocido): debe fallar cerrado, JAMAS caer
      // a la raiz legacy compartida (que si tiene el archivo, si se buscara ahi).
      const desconocido = await mt1f5bGetTexto(port, `/uploads/productos/${nombreLegacy}`, `no-existe-${Date.now()}.${MT1F3_DOMINIO}`);
      assertEqual(desconocido.status, 404, "tenant desconocido: no se sirve ni el archivo legacy");
      assertSame(desconocido.texto.includes("CEBO-LEGACY"), false, "no se filtra contenido de la raiz legacy compartida");

      // LOCAL/APEX tampoco tienen candidato de tenant.
      const local = await mt1f5bGetTexto(port, `/uploads/productos/${nombreLegacy}`, "127.0.0.1");
      assertEqual(local.status, 404, "Host LOCAL: no se sirve el archivo legacy");
      const apex = await mt1f5bGetTexto(port, `/uploads/productos/${nombreLegacy}`, MT1F3_DOMINIO);
      assertEqual(apex.status, 404, "Host APEX/RESERVED: no se sirve el archivo legacy");
    });
  } finally {
    mt1f5bLimpiarLegacy("productos", nombreLegacy);
    await mt1f1Limpiar(escenario);
  }
}

async function testMT1F5BLegacySoloGuernica() {
  const tenants = [
    { tag: "guernica", slug: "guernica", dbPath: bootstrapFreshRegisteredTenantDb(), empresa: null },
    { tag: "otro", slug: mt1f1Slug("otro"), dbPath: bootstrapFreshRegisteredTenantDb(), empresa: null }
  ];
  const controlDbPath = tempDbPath();
  const decoyPath = tempDbPath();
  const nombreCasoA = mt1f5bNombreTest("caso-a");
  const nombreCasoB = mt1f5bNombreTest("caso-b");
  let escenario = { tenants, controlDbPath };
  try {
    const controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
    try {
      for (const tenant of tenants) {
        tenant.empresa = await registrarEmpresa(controlDb, { slug: tenant.slug, nombre: `MT1F5B ${tenant.tag}`, dbPath: path.basename(tenant.dbPath), activa: 1 });
      }
    } finally {
      await closeControlDb(controlDb);
    }
    for (const tenant of tenants) {
      await insertarTenantIdentityTest(tenant.dbPath, tenant.empresa.id, tenant.slug);
    }
    const [guernica, otro] = tenants;
    assertSame(guernica.slug, "guernica", "el tenant de prueba usa exactamente el slug guernica");

    // Caso A: mismo archivo relativo en tenant-root y legacy con bytes distintos -- gana tenant-root.
    mt1f5bSembrarTenant(guernica.empresa.id, "productos", nombreCasoA, "TENANT-ROOT");
    mt1f5bSembrarLegacy("productos", nombreCasoA, "LEGACY-ROOT");
    // Caso B: archivo SOLO en legacy -- Guernica lo recibe via fallback de solo-lectura.
    mt1f5bSembrarLegacy("productos", nombreCasoB, "LEGACY-ONLY");

    await mt1f3ConServidor(mt1f3EntornoMulti(escenario, decoyPath), async (servidor) => {
      const port = servidor.port;

      const casoA = await mt1f5bGetTexto(port, `/uploads/productos/${nombreCasoA}`, mt1f3Host(guernica));
      assertEqual(casoA.status, 200, "caso A: guernica lee el archivo existente en ambas raices");
      assertSame(casoA.texto, "TENANT-ROOT", "caso A: gana la raiz tenant-especifica, no la legacy");

      const casoB = await mt1f5bGetTexto(port, `/uploads/productos/${nombreCasoB}`, mt1f3Host(guernica));
      assertEqual(casoB.status, 200, "caso B: guernica lee el archivo que SOLO existe en legacy");
      assertSame(casoB.texto, "LEGACY-ONLY", "caso B: sirve los bytes legacy via fallback de solo lectura");

      // El mismo archivo solo-legacy, pedido por un tenant NO guernica: jamas cae a legacy.
      const otroTenant = await mt1f5bGetTexto(port, `/uploads/productos/${nombreCasoB}`, mt1f3Host(otro));
      assertEqual(otroTenant.status, 404, "un tenant no-guernica NUNCA recibe el fallback legacy");
      assertSame(otroTenant.texto.includes("LEGACY-ONLY"), false, "no se filtra contenido legacy a un tenant no-guernica");
    });
  } finally {
    mt1f5bLimpiarTenant(tenants[0].empresa?.id);
    mt1f5bLimpiarTenant(tenants[1].empresa?.id);
    mt1f5bLimpiarLegacy("productos", nombreCasoA);
    mt1f5bLimpiarLegacy("productos", nombreCasoB);
    await mt1f1Limpiar(escenario);
  }
}

async function testMT1F5BSingleConservaUploadsLegacy() {
  // El modulo tenantUploadStorage solo distingue por tenancyMode ("single"/"multi"); ATLAS_AUTH_MODE
  // (legacy vs central) no participa de su decision -- legacy+single y central+single comparten la
  // MISMA rama "single" (ya probado por smoke: getTenantContext nunca se consulta en modo single).
  // Aca se prueba end-to-end sobre legacy+single, la configuracion mas simple del harness real.
  const dbPath = bootstrapFreshTestDb();
  const nombreLegacy = mt1f5bNombreTest("single-legacy");
  try {
    mt1f5bSembrarLegacy("productos", nombreLegacy, "SINGLE-LEGACY-OK");
    await withServer(dbPath, async (baseUrl) => {
      const port = Number(new URL(baseUrl).port);
      const respuesta = await mt1f5bGetTexto(port, `/uploads/productos/${nombreLegacy}`, undefined);
      assertEqual(respuesta.status, 200, "single mode sirve desde la raiz legacy compartida sin subdirectorio de tenant");
      assertSame(respuesta.texto, "SINGLE-LEGACY-OK", "bytes correctos, sin migracion ni reescritura de URL");
    });

    const { crearTenantUploadStorage } = require("../backend/tenantUploadStorage");
    const prohibido = () => { throw new Error("getTenantContext no debe consultarse en modo single"); };
    const storage = crearTenantUploadStorage({ tenancyMode: "single", getTenantContext: prohibido, uploadsRoot: path.join(ROOT, "uploads") });
    const destino = storage.resolverDestinoEscritura({ categoria: "productos", filename: "cualquiera.png" });
    assertSame(destino.ruta, path.join(ROOT, "uploads", "productos", "cualquiera.png"), "escritura single = raiz legacy, sin uploads/tenants");
  } finally {
    mt1f5bLimpiarLegacy("productos", nombreLegacy);
    fs.rmSync(dbPath, { force: true });
  }
}

async function testMT1F5BTraversalFailsClosed() {
  const escenario = await mt1f1CrearEscenario(["a"]);
  const decoyPath = tempDbPath();
  const [tenantA] = escenario.tenants;
  const nombreValido = mt1f5bNombreTest("valido-control");
  try {
    mt1f5bSembrarTenant(tenantA.empresa.id, "productos", nombreValido, "ARCHIVO-VALIDO");
    await mt1f3ConServidor(mt1f3EntornoMulti(escenario, decoyPath), async (servidor) => {
      const port = servidor.port;
      const host = mt1f3Host(tenantA);

      const control = await mt1f5bGetTexto(port, `/uploads/productos/${nombreValido}`, host);
      assertEqual(control.status, 200, "control: un filename valido generado por el server SI se sirve");
      assertSame(control.texto, "ARCHIVO-VALIDO", "control: bytes correctos");

      const intentos = [
        `/uploads/productos/${encodeURIComponent("../" + nombreValido)}`,
        `/uploads/productos/..%2f..%2fpackage.json`,
        `/uploads/productos/..%5c..%5cpackage.json`,
        `/uploads/productos/%2e%2e%2fpackage.json`,
        `/uploads/noexiste/${nombreValido}`,
        `/uploads/productos/sub/${nombreValido}`,
        `/uploads/productos/%2fetc%2fpasswd`
      ];
      for (const ruta of intentos) {
        const respuesta = await mt1f5bGetTexto(port, ruta, host);
        assertEqual(respuesta.status, 404, `traversal/invalido rechazado: ${ruta} (status=${respuesta.status})`);
        assertSame(respuesta.texto.includes("ARCHIVO-VALIDO"), false, `${ruta}: no filtra contenido de otro archivo`);
      }
    });
  } finally {
    mt1f5bLimpiarTenant(tenantA.empresa.id);
    await mt1f1Limpiar(escenario);
  }
}

// ====================================================================================================
// MT-1F5C1: schema/repositorio/crypto de credenciales de integraciones tenant-owned. Ver
// MT-1F5C-D1/D1A/D1B/D1C para la autoridad de diseno completa.
// ====================================================================================================

// DB disposable con SOLO el baseline 001 aplicado (BEHIND respecto del catalogo real de 2 entradas)
// -- fixture necesaria para probar la migracion 001->002 en si misma. bootstrapFreshTestDb() ya deja
// el catalogo COMPLETO aplicado (necesario para que el boot gate real la acepte via
// stamparHistorialBaselineActual) -- aca se revierte EXACTAMENTE lo que up002TenantIntegrationCredentials
// hizo (las 2 tablas nuevas, nada mas) y se recorta el historial a solo la fila 1, para reconstruir
// el estado fisico real de una DB legacy nunca migrada a 002.
async function mt1f5c1DbSoloBaseline001() {
  const dbPath = bootstrapFreshTestDb();
  await runSql(dbPath, "DROP TABLE integraciones_tenant_secretos");
  await runSql(dbPath, "DROP TABLE integraciones_tenant");
  await runSql(dbPath, "DELETE FROM atlas_schema_migrations WHERE sequence <> 1");
  return dbPath;
}

// Ejecuta una secuencia de operaciones del servicio (tenancyMode=single) en un proceso hijo fresco,
// con GUERNICA_DB_PATH apuntando a `dbPath` -- necesario porque backend/db.js resuelve su path de
// singleton UNA sola vez al cargar el modulo (ya cargado por este mismo test runner al arrancar), asi
// que la unica forma segura de dirigir el singleton legacy hacia una DB disposable especifica es un
// proceso nuevo. Nunca toca database/guernica.db: cada test arma su propia DB disposable primero.
function mt1f5c1ScriptServicioSingle(operaciones) {
  const servicioPath = path.join(ROOT, "backend", "services", "integracionTenantService.js");
  const contextPath = path.join(ROOT, "backend", "tenantRequestContext.js");
  return [
    `const { crearIntegracionTenantService } = require(${JSON.stringify(servicioPath)});`,
    `const { getTenantContext } = require(${JSON.stringify(contextPath)});`,
    `const servicio = crearIntegracionTenantService({ tenancyMode: "single", getTenantContext });`,
    `const operaciones = ${JSON.stringify(operaciones)};`,
    "(async () => {",
    "  const resultados = [];",
    "  for (const op of operaciones) {",
    "    try {",
    "      let valor;",
    '      if (op.metodo === "establecerCredencial") valor = await servicio.establecerCredencial(op.provider, op.secreto, op.opts || {});',
    '      else if (op.metodo === "quitarCredencial") valor = await servicio.quitarCredencial(op.provider);',
    '      else if (op.metodo === "establecerHabilitado") valor = await servicio.establecerHabilitado(op.provider, op.enabled);',
    '      else if (op.metodo === "resolverCredencial") valor = await servicio.resolverCredencial(op.provider);',
    '      else if (op.metodo === "leerEstadoSeguro") valor = await servicio.leerEstadoSeguro(op.provider);',
    '      else throw new Error("metodo desconocido: " + op.metodo);',
    "      resultados.push({ ok: true, valor });",
    "    } catch (error) {",
    "      resultados.push({ ok: false, code: error.code || null, message: error.message });",
    "    }",
    "  }",
    "  process.stdout.write(JSON.stringify(resultados));",
    "})();"
  ].join("\n");
}

function ejecutarWorkerServicioSingle(dbPath, operaciones, envExtra = {}) {
  return new Promise((resolve, reject) => {
    const script = mt1f5c1ScriptServicioSingle(operaciones);
    const child = spawn(process.execPath, ["-e", script], {
      cwd: ROOT,
      env: { ...process.env, GUERNICA_DB_PATH: dbPath, ...envExtra }
    });
    let out = "";
    let err = "";
    child.stdout.on("data", (d) => { out += d.toString(); });
    child.stderr.on("data", (d) => { err += d.toString(); });
    child.on("exit", () => {
      if (!out.trim()) { reject(new Error(`ejecutarWorkerServicioSingle: sin output. stderr: ${err}`)); return; }
      try { resolve(JSON.parse(out.trim())); } catch (parseError) { reject(new Error(`ejecutarWorkerServicioSingle: output invalido: ${out}\nstderr:${err}`)); }
    });
  });
}

function mt1f5c1MasterKeyDisponible(envExtra = {}) {
  return { ATLAS_INTEGRATION_MASTER_KEY_B64: crypto.randomBytes(32).toString("base64"), ...envExtra };
}

async function testMT1F5C1Catalogo002Real() {
  assertEqual(BUSINESS_MIGRATIONS.length, 2, "catalogo debe tener exactamente 2 entradas");
  assertEqual(BUSINESS_MIGRATIONS[0].sequence, 1, "primera entrada sequence=1");
  assertSame(BUSINESS_MIGRATIONS[0].migrationId, "001_legacy_runtime_baseline", "primera entrada es el baseline");
  assertSame(BUSINESS_MIGRATIONS[0].kind, "BASELINE", "primera entrada kind BASELINE");
  assertSame(BUSINESS_MIGRATIONS[0].up, undefined, "el baseline no tiene up");
  assertEqual(BUSINESS_MIGRATIONS[1].sequence, 2, "segunda entrada sequence=2");
  assertSame(BUSINESS_MIGRATIONS[1].migrationId, "002_tenant_integration_credentials", "segunda entrada es la migration real");
  assertSame(BUSINESS_MIGRATIONS[1].kind, "MIGRATION", "segunda entrada kind MIGRATION");
  assertSame(typeof BUSINESS_MIGRATIONS[1].up, "function", "segunda entrada tiene up(db) callable");
  assertSame(BUSINESS_MIGRATIONS[2], undefined, "no existe una tercera entrada (003)");
}

